from typing import Any, Dict, Optional


class EmailPasswordRequest:
    def __init__(self, email: str, password: str):
        self.email = email
        self.password = password


class EmailPasswordResponse:
    def __init__(self, success: bool, message: Optional[str] = None):
        self.success = success
        self.message = message


def normalize_email_password_response(response: Dict[str, Any]) -> EmailPasswordResponse:
    success = response.get('success', False)
    message = response.get('message', None)
    return EmailPasswordResponse(success=success, message=message)

import firebase_admin
from firebase_admin import auth

def start_password_reset(email):
    if not firebase_admin._apps:
        firebase_admin.initialize_app()
    try:
        auth.generate_password_reset_link(email)
        print(f'Password reset link sent to {email}')
    except Exception as e:
        print(f'Error sending password reset link: {e}')

if __name__ == '__main__':\n    email = 'user@example.com'
    start_password_reset(email)

import boto3

def refresh_session(refresh_token):
    client = boto3.client('cognito-idp', region_name='us-east-1')
    try:
        response = client.initiate_auth(
            ClientId='YOUR_COGNITO_CLIENT_ID',
            AuthFlow='REFRESH_TOKEN_AUTH',
            AuthParameters={'REFRESH_TOKEN': refresh_token}
        )
        return response['AuthenticationResult']
    except client.exceptions.NotAuthorizedException as e:
        print(f'Refresh token is invalid: {e}')
        return None
